DELETE FROM pix_movie_deck_entries WHERE deck_key = 'year-1962';
--> statement-breakpoint
INSERT INTO pix_movie_deck_entries (deck_key,imdb_id,position,created_at) SELECT 'year-1962',imdb_id,ROW_NUMBER() OVER (ORDER BY CASE WHEN json_extract(attributes_json,'$.deck')='year-1962' THEN 0 ELSE 1 END,title COLLATE NOCASE,imdb_id),CAST(strftime('%s','now') AS INTEGER) * 1000 FROM pix_movie_stats WHERE release_year=1962 AND poster_key<>'' ORDER BY CASE WHEN json_extract(attributes_json,'$.deck')='year-1962' THEN 0 ELSE 1 END,title COLLATE NOCASE,imdb_id;
--> statement-breakpoint
INSERT INTO pix_movie_decks (deck_key,label,release_year,target_size,active,sort_order,created_at,updated_at) VALUES ('year-1961','1961 Movies',1961,100,1,65,CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(deck_key) DO UPDATE SET label=excluded.label,release_year=excluded.release_year,target_size=MAX(pix_movie_decks.target_size, excluded.target_size),active=excluded.active,sort_order=excluded.sort_order,updated_at=excluded.updated_at;
